/** Compare the optimized preview against the former direct per-pixel implementation.
 * Supply decoded preset textures in FLOW_PREVIEW_CACHE (generated by Pillow).
 * Exact equality is checked on real source pixels and the current mask maps.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import {fileURLToPath} from 'node:url';
import {performance} from 'node:perf_hooks';
import {sampleFlowSection,paintFlowSection} from '../public/flow-views.js';
import {dot,worldToSource} from '../public/planes.js';
import {capColor,anatomyColor,buildAnatomyPalette} from '../public/render-styles.js';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const cache=process.env.FLOW_PREVIEW_CACHE||'/workspace/data/flow-views-v5';
const metadata=JSON.parse(fs.readFileSync(path.join(root,'public/assets/flow-views-v5.json')));
const anatomyMeta=JSON.parse(fs.readFileSync(path.join(root,'public/assets/anatomy/manifest.json')));
const cleanup={dimensions:[238,238,265],data:zlib.gunzipSync(fs.readFileSync(path.join(root,'public/assets/cleanup/heart-support.raw.gz')))};
const anatomy={dimensions:anatomyMeta.dimensions,data:zlib.gunzipSync(fs.readFileSync(path.join(root,'public',anatomyMeta.volumeUrl)))};
const colors=buildAnatomyPalette(anatomyMeta.labels),extent=[474/529,1,474/529],longestMm=529*.3176;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function sampleMap(map,x,y,z){const [nx,ny,nz]=map.dimensions;return map.data[Math.round(clamp(x,0,1)*(nx-1))+nx*(Math.round(clamp(y,0,1)*(ny-1))+ny*Math.round(clamp(z,0,1)*(nz-1)))];}
const a={cleanup,anatomy,sample:sampleMap};
function reference(sample,p,s,contrast,flip){
 const {data,width,height,plane}=sample,w=600,h=600,rgba=new Uint8ClampedArray(w*h*4);
 const span=Math.max(p.focusWidthMm,p.focusHeightMm)/longestMm;
 const target=plane.target,delta=target.map((v,i)=>v-plane.center[i]),uc=dot(delta,plane.right)/plane.width+.5,vc=.5-dot(delta,plane.up)/plane.height;
  for(let row=0;row<h;row++){
   const v=(.5-row/(h-1))*span,ty=vc-v/plane.height;const sourceRow=Math.round(ty*(height-1));
   for(let col=0;col<w;col++){
    const u=((flip?w-1-col:col)/(w-1)-.5)*span,tx=uc+u/plane.width,sourceCol=Math.round(tx*(width-1));
    const value=sourceRow<0||sourceRow>=height||sourceCol<0||sourceCol>=width?0:data[sourceCol+sourceRow*width]/255;
    const i=(row*w+col)*4;let rgb=[0,0,0];
    if(value>0){
     rgb=capColor(value,contrast,s.palette);
     let xyz;
     if(a&&((s.cleanupEnabled!==false&&a.cleanup)||(s.palette===5&&a.anatomy)))xyz=worldToSource(target.map((x,k)=>x+plane.right[k]*u+plane.up[k]*v),extent);
     const excluded=xyz&&s.cleanupEnabled!==false&&a.cleanup&&!a.sample(a.cleanup,...xyz);
     if(excluded||(s.palette===4&&value<s.threshold))rgb=[0,0,0];
     else if(xyz&&s.palette===5&&a.anatomy&&value>s.threshold)rgb=anatomyColor(rgb,a.sample(a.anatomy,...xyz),colors,s.anatomyOpacity??.65,s.anatomySelected??0);
    }
    rgba[i]=Math.pow(Math.max(0,rgb[0]),.89)*255;rgba[i+1]=Math.pow(Math.max(0,rgb[1]),.89)*255;rgba[i+2]=Math.pow(Math.max(0,rgb[2]),.89)*255;rgba[i+3]=255;
   }
  }

 return rgba;
}
const cases=[],baseline=[],recolor=[],sampling=[];
for(const p of metadata.presets){
 const sample={data:new Uint8Array(fs.readFileSync(path.join(cache,p.id+'.raw'))),width:p.texture.width,height:p.texture.height,plane:p.world};
 for(const flip of [false,true]){
  let start=performance.now();const grid=sampleFlowSection(sample,p,{width:600,height:600,longestMm,extent,flip,cleanup,anatomy});sampling.push(performance.now()-start);
  const styles=[{palette:4,cleanupEnabled:true,threshold:.28,anatomyOpacity:.65,anatomySelected:0},{palette:5,cleanupEnabled:true,threshold:.28,anatomyOpacity:.65,anatomySelected:2}];
  if(p.id==='rv-inflow')for(let palette=0;palette<6;palette++)styles.push({palette,cleanupEnabled:false,threshold:.31,anatomyOpacity:.45,anatomySelected:0});
  for(const settings of styles){
   const contrast=settings.cleanupEnabled?1.65:2.1;
   start=performance.now();const old=reference(sample,p,settings,contrast,flip);baseline.push(performance.now()-start);
   start=performance.now();const actual=paintFlowSection(grid,settings,contrast,colors);recolor.push(performance.now()-start);
   assert.deepEqual(actual,old,`${p.id} flip=${flip} palette=${settings.palette} cleanup=${settings.cleanupEnabled}`);
   cases.push({preset:p.id,flip,palette:settings.palette,cleanup:settings.cleanupEnabled,selected:settings.anatomySelected,identical:true});
  }
 }
}
const median=v=>[...v].sort((a,b)=>a-b)[Math.floor(v.length/2)];
const result={passed:true,comparisons:cases.length,dimensions:[600,600],allPixelsIdentical:true,presets:8,anatomyRevision:anatomyMeta.revision,timingContext:'Node CPU microbenchmark on this machine; not browser end-to-end performance',medianDirectMs:median(baseline),medianCachedRecolorMs:median(recolor),medianSourceSamplingMs:median(sampling),cases};
fs.writeFileSync(path.join(root,'docs/flow-views-preview-validation-v5.json'),JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({...result,cases:undefined}));
